import { expectLogic } from 'kea-test-utils'

import { lemonToast } from '@posthog/lemon-ui'

import { dayjs } from 'lib/dayjs'

import { useMocks } from '~/mocks/jest'
import { initKeaTests } from '~/test/init'
import { AnyPropertyFilter, PropertyFilterType, PropertyOperator } from '~/types'

import type {
    HogFlowApi,
    HogFlowBatchJobApi,
    HogFlowScheduleApi,
} from 'products/workflows/frontend/generated/api.schemas'

import { ONE_TIME_RRULE } from '../Workflows/hogflows/steps/components/rrule-helpers'
import { canMoveBroadcastToDraft } from './broadcastsLogic'
import { broadcastWizardLogic } from './broadcastWizardLogic'

const BROADCAST_ID = '01a05e5e-38c2-0000-b81a-21fe48581914'

const filterOn = (value: string): AnyPropertyFilter[] => [
    { key: 'plan', value, operator: PropertyOperator.Exact, type: PropertyFilterType.Person },
]

const triggerFilters = (flow: Record<string, any>): unknown =>
    (flow.actions ?? []).find((action: Record<string, any>) => action.type === 'trigger')?.config?.filters

const makeSchedule = (overrides: Partial<HogFlowScheduleApi> = {}): HogFlowScheduleApi =>
    ({
        id: 'schedule-old',
        rrule: ONE_TIME_RRULE,
        starts_at: dayjs().add(3, 'day').startOf('minute').toISOString(),
        timezone: 'UTC',
        status: 'active',
        next_run_at: null,
        ...overrides,
    }) as HogFlowScheduleApi

const makeBroadcast = (status: string, schedules: HogFlowScheduleApi[] = []): Record<string, any> => ({
    id: BROADCAST_ID,
    name: 'Spring launch',
    status,
    origin_product: 'broadcasts',
    conversion: null,
    email_sending_rate_limit: null,
    schedules,
    actions: [
        {
            id: 'trigger_node',
            type: 'trigger',
            config: { type: 'batch', filters: { properties: filterOn('free') } },
        },
        {
            id: 'email_node',
            type: 'function_email',
            config: {
                inputs: {
                    email: {
                        value: {
                            to: { email: '{{ person.properties.email }}', name: '' },
                            from: { integrationId: 7, email: 'sender@example.com' },
                            subject: 'Hello there',
                            html: '<p>Hi</p>',
                            text: '',
                            design: null,
                        },
                    },
                },
            },
        },
        { id: 'exit_node', type: 'exit', config: {} },
    ],
})

// An in-memory stand-in for the hog flow API. It mirrors the server rules this feature depends on:
// schedule status is read-only, and a save that changes the audience pauses every active schedule.
class FakeHogFlowServer {
    flow: Record<string, any>
    schedules: HogFlowScheduleApi[]
    batchJobs: HogFlowBatchJobApi[] = []
    failures: { patchStatus?: string; deleteSchedule?: boolean; createSchedule?: boolean } = {}
    private nextScheduleId = 1

    constructor(flow: Record<string, any>) {
        this.schedules = flow.schedules ?? []
        this.flow = flow
    }

    serializedFlow(): Record<string, any> {
        return { ...this.flow, schedules: [...this.schedules] }
    }

    install(): void {
        useMocks({
            get: {
                [`/api/projects/:team_id/hog_flows/${BROADCAST_ID}/`]: () => this.serializedFlow(),
                [`/api/projects/:team_id/hog_flows/${BROADCAST_ID}/schedules/`]: () => [...this.schedules],
                [`/api/projects/:team_id/hog_flows/${BROADCAST_ID}/batch_jobs/`]: () => [...this.batchJobs],
            },
            post: {
                '/api/projects/:team_id/hog_flows/user_blast_radius/': () => ({
                    affected: 10,
                    total: 100,
                    limit: 1000,
                    dedupe_key: 'email',
                    confirm_token: 'fake-confirm-token',
                }),
                [`/api/projects/:team_id/hog_flows/${BROADCAST_ID}/schedules/`]: async ({ request }) => {
                    if (this.failures.createSchedule) {
                        return [500, { detail: 'schedule create failed' }]
                    }
                    const body = (await request.json()) as Record<string, any>
                    const schedule = makeSchedule({
                        ...body,
                        id: `schedule-new-${this.nextScheduleId++}`,
                        status: 'active',
                    } as Partial<HogFlowScheduleApi>)
                    this.schedules.push(schedule)
                    return [201, schedule]
                },
                [`/api/projects/:team_id/hog_flows/${BROADCAST_ID}/batch_jobs/`]: () => {
                    const job = { id: 'job-1', status: 'queued' } as HogFlowBatchJobApi
                    this.batchJobs.push(job)
                    return [201, job]
                },
            },
            patch: {
                [`/api/projects/:team_id/hog_flows/${BROADCAST_ID}/`]: async ({ request }) => {
                    const body = (await request.json()) as Record<string, any>
                    if (body.status && body.status === this.failures.patchStatus) {
                        return [500, { detail: 'status change failed' }]
                    }
                    const before = this.flow
                    this.flow = { ...this.flow, ...body }
                    if (
                        body.actions &&
                        JSON.stringify(triggerFilters(before)) !== JSON.stringify(triggerFilters(this.flow))
                    ) {
                        this.schedules = this.schedules.map((schedule) =>
                            schedule.status === 'active'
                                ? ({ ...schedule, status: 'paused', next_run_at: null } as HogFlowScheduleApi)
                                : schedule
                        )
                    }
                    return this.serializedFlow()
                },
            },
            delete: {
                [`/api/projects/:team_id/hog_flows/${BROADCAST_ID}/schedules/:schedule_id/`]: ({ params }) => {
                    if (this.failures.deleteSchedule) {
                        return [500, { detail: 'schedule delete failed' }]
                    }
                    this.schedules = this.schedules.filter((schedule) => schedule.id !== params.schedule_id)
                    return [204]
                },
            },
        })
    }
}

describe('broadcast lifecycle', () => {
    let server: FakeHogFlowServer
    let logic: ReturnType<typeof broadcastWizardLogic.build>

    const mountWith = async (flow: Record<string, any>): Promise<void> => {
        server = new FakeHogFlowServer(flow)
        server.install()
        logic = broadcastWizardLogic({ id: BROADCAST_ID })
        logic.mount()
        await expectLogic(logic).toDispatchActions(['loadBroadcastSuccess']).toFinishAllListeners()
    }

    const launch = async (): Promise<void> => {
        await expectLogic(logic, () => logic.actions.launchBroadcast()).toFinishAllListeners()
    }

    beforeEach(() => {
        initKeaTests()
        jest.spyOn(lemonToast, 'success').mockImplementation(() => undefined as any)
        jest.spyOn(lemonToast, 'error').mockImplementation(() => undefined as any)
    })

    afterEach(() => {
        logic?.unmount()
        jest.restoreAllMocks()
    })

    describe('relaunching a scheduled broadcast', () => {
        it.each([
            ['a first launch with no schedule yet', [] as HogFlowScheduleApi[], false],
            ['a draft whose earlier schedule is still active', [makeSchedule()], false],
            ['a draft whose schedule gets paused by an audience edit', [makeSchedule()], true],
            [
                'a draft whose schedule came due while it was a draft',
                [makeSchedule({ starts_at: dayjs().subtract(1, 'day').toISOString(), next_run_at: null })],
                false,
            ],
        ])('leaves exactly one active schedule at the chosen time for %s', async (_name, schedules, editAudience) => {
            await mountWith(makeBroadcast('draft', schedules))
            const sendAt = dayjs().add(5, 'day').startOf('minute').toISOString()
            logic.actions.setScheduleMode('later')
            logic.actions.setSendAt(sendAt)
            if (editAudience) {
                logic.actions.setAudienceProperties(filterOn('pro'))
            }

            await launch()

            expect(server.flow.status).toBe('active')
            expect(server.schedules).toEqual([
                expect.objectContaining({ status: 'active', starts_at: sendAt, rrule: ONE_TIME_RRULE }),
            ])
            expect(lemonToast.success).toHaveBeenCalledWith('Broadcast scheduled')
        })

        it('replaces a schedule created after the wizard loaded', async () => {
            await mountWith(makeBroadcast('draft'))
            server.schedules.push(makeSchedule({ id: 'schedule-from-elsewhere' }))
            const sendAt = dayjs().add(5, 'day').startOf('minute').toISOString()
            logic.actions.setScheduleMode('later')
            logic.actions.setSendAt(sendAt)

            await launch()

            expect(server.schedules.map((schedule) => schedule.starts_at)).toEqual([sendAt])
        })

        it('removes an old schedule when relaunched to send now', async () => {
            await mountWith(makeBroadcast('draft', [makeSchedule()]))
            logic.actions.setScheduleMode('now')

            await launch()

            expect(server.flow.status).toBe('active')
            expect(server.batchJobs).toHaveLength(1)
            expect(server.schedules).toEqual([])
        })

        it.each([
            ['deleting the old schedule fails', 'deleteSchedule' as const, ['schedule-old']],
            ['creating the new schedule fails', 'createSchedule' as const, []],
        ])('returns the broadcast to draft when %s', async (_name, failure, remainingScheduleIds) => {
            await mountWith(makeBroadcast('draft', [makeSchedule()]))
            server.failures[failure] = true
            logic.actions.setScheduleMode('later')
            logic.actions.setSendAt(dayjs().add(5, 'day').startOf('minute').toISOString())

            await launch()

            expect(server.flow.status).toBe('draft')
            expect(server.schedules.map((schedule) => schedule.id)).toEqual(remainingScheduleIds)
            expect(logic.values.launching).toBe(false)
            expect(lemonToast.success).not.toHaveBeenCalled()
            expect(lemonToast.error).toHaveBeenCalledWith(expect.stringContaining("Couldn't launch the broadcast"))
        })
    })

    describe('moving a scheduled broadcast back to draft', () => {
        it('makes the broadcast editable again and keeps its configuration', async () => {
            const scheduled = makeSchedule()
            await mountWith(makeBroadcast('active', [scheduled]))
            expect(logic.values.isReadOnly).toBe(true)

            await expectLogic(logic, () => logic.actions.moveToDraft()).toFinishAllListeners()

            expect(server.flow.status).toBe('draft')
            expect(logic.values).toMatchObject({
                isReadOnly: false,
                movingToDraft: false,
                scheduleMode: 'later',
                sendAt: scheduled.starts_at,
                audienceProperties: filterOn('free'),
                email: expect.objectContaining({ subject: 'Hello there' }),
            })
        })

        it('keeps the broadcast live and read-only when the change fails', async () => {
            await mountWith(makeBroadcast('active', [makeSchedule()]))
            server.failures.patchStatus = 'draft'

            await expectLogic(logic, () => logic.actions.moveToDraft()).toFinishAllListeners()

            expect(server.flow.status).toBe('active')
            expect(logic.values).toMatchObject({ isReadOnly: true, movingToDraft: false })
            expect(lemonToast.error).toHaveBeenCalled()
        })

        it.each([
            ['a live broadcast waiting on its schedule', 'active', [makeSchedule()], [], true],
            ['a recurring broadcast between runs', 'active', [makeSchedule()], ['completed'], true],
            ['a broadcast sent immediately', 'active', [], ['completed'], false],
            ['a broadcast whose send is running', 'active', [makeSchedule()], ['active'], false],
            ['a one-time schedule that already fired', 'active', [makeSchedule({ status: 'completed' })], [], false],
            ['a draft', 'draft', [makeSchedule()], [], false],
            ['an archived broadcast', 'archived', [makeSchedule()], [], false],
        ])('offers the move for %s: %s', (_name, status, schedules, jobStatuses, expected) => {
            const jobs = jobStatuses.map((jobStatus) => ({ status: jobStatus }) as HogFlowBatchJobApi)
            expect(canMoveBroadcastToDraft(makeBroadcast(status, schedules) as HogFlowApi, jobs)).toBe(expected)
        })
    })
})

