    HogFlowBatchJobApi,
    HogFlowMinimalApi,""",1)
anchor="// A batch send's email metrics"
helper='''const RUNNING_BATCH_JOB_STATUSES = ['waiting', 'queued', 'active']

// A live broadcast can go back to draft while it still has a send ahead of it. A paused schedule
// counts: relaunching from draft is how it gets an active schedule again. A run already in progress
// is not stopped by a status change, so the move is not offered then.
export function canMoveBroadcastToDraft(broadcast: HogFlowApi | null, batchJobs: HogFlowBatchJobApi[]): boolean {
    if (broadcast?.status !== 'active') {
        return false
    }
    if (batchJobs.some((job) => RUNNING_BATCH_JOB_STATUSES.includes(job.status ?? ''))) {
        return false
    }
    return (broadcast.schedules ?? []).some((schedule) => schedule.status !== 'completed')
}

'''
s=s.replace(anchor, helper+anchor,1)
s=s.replace("if (['waiting', 'queued', 'active'].includes(latestJob.status ?? '')) {","if (RUNNING_BATCH_JOB_STATUSES.includes(latestJob.status ?? '')) {")
open(p,'w').write(s)
