import '@testing-library/jest-dom'

import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react'
import { BindLogic, Provider } from 'kea'
import { expectLogic } from 'kea-test-utils'

import { dayjs } from 'lib/dayjs'

import { useMocks } from '~/mocks/jest'
import { initKeaTests } from '~/test/init'

import { BroadcastSummary } from './BroadcastSummary'
import { broadcastWizardLogic } from './broadcastWizardLogic'

const BROADCAST_ID = '01a05e5e-38c2-0000-b81a-21fe48581915'

describe('BroadcastSummary', () => {
    let flowStatus: string

    const renderSummary = async (userAccessLevel: string): Promise<void> => {
        useMocks({
            get: {
                [`/api/projects/:team_id/hog_flows/${BROADCAST_ID}/`]: () => ({
                    id: BROADCAST_ID,
                    name: 'Spring launch',
                    status: flowStatus,
                    origin_product: 'broadcasts',
                    user_access_level: userAccessLevel,
                    actions: [],
                    schedules: [
                        {
                            id: 'schedule-1',
                            rrule: 'FREQ=DAILY;COUNT=1',
                            starts_at: dayjs().add(3, 'day').toISOString(),
                            timezone: 'UTC',
                            status: 'active',
                        },
                    ],
                }),
                [`/api/projects/:team_id/hog_flows/${BROADCAST_ID}/batch_jobs/`]: () => [],
            },
            patch: {
                [`/api/projects/:team_id/hog_flows/${BROADCAST_ID}/`]: async ({ request }) => {
                    flowStatus = ((await request.json()) as Record<string, any>).status ?? flowStatus
                    return { id: BROADCAST_ID, status: flowStatus, origin_product: 'broadcasts', schedules: [] }
                },
            },
        })
        const logic = broadcastWizardLogic({ id: BROADCAST_ID })
        logic.mount()
        await expectLogic(logic).toDispatchActions(['loadBroadcastSuccess', 'loadBatchJobsSuccess'])
        render(
            <Provider>
                <BindLogic logic={broadcastWizardLogic} props={{ id: BROADCAST_ID }}>
                    <BroadcastSummary />
                </BindLogic>
            </Provider>
        )
    }

    beforeEach(() => {
        flowStatus = 'active'
        initKeaTests()
    })

    afterEach(() => {
        cleanup()
    })

    it.each([
        ['an editor', 'editor', false],
        ['a viewer', 'viewer', true],
    ])('lets %s move a scheduled broadcast to draft only with edit access', async (_name, level, disabled) => {
        await renderSummary(level)

        const button = await screen.findByText('Move to draft')
        expect(button.closest('button')?.getAttribute('aria-disabled') === 'true').toBe(disabled)
    })

    it('moves the broadcast to draft only after the dialog is confirmed', async () => {
        await renderSummary('editor')

        fireEvent.click(await screen.findByText('Move to draft'))
        fireEvent.click(await screen.findByText('Keep scheduled'))
        expect(flowStatus).toBe('active')

        fireEvent.click(await screen.findByText('Move to draft'))
        const confirm = (await screen.findAllByText('Move to draft')).find((el) => el.closest('.LemonModal'))
        fireEvent.click(confirm!)

        await waitFor(() => expect(flowStatus).toBe('draft'))
    })
})

import { expectLogic } from 'kea-test-utils'

import { lemonToast } from '@posthog/lemon-ui'

import { dayjs } from 'lib/dayjs'

import { initKeaTests } from '~/test/init'

import * as generatedApi from 'products/workflows/frontend/generated/api'
import type { HogFlowApi, HogFlowBatchJobApi, HogFlowScheduleApi } from 'products/workflows/frontend/generated/api.schemas'

import { ONE_TIME_RRULE } from '../Workflows/hogflows/steps/components/rrule-helpers'
import { broadcastWizardLogic } from './broadcastWizardLogic'

jest.mock('products/workflows/frontend/generated/api')

const api = jest.mocked(generatedApi)

const BROADCAST_ID = 'broadcast-1'
const WEEKLY_RRULE = 'FREQ=WEEKLY;INTERVAL=1;BYDAY=MO'
const AUDIENCE = [{ key: 'plan', value: ['pro'], operator: 'exact', type: 'person' }]
const WIDER_AUDIENCE = [{ key: 'plan', value: ['pro', 'free'], operator: 'exact', type: 'person' }]

// Relative to now, so the "send time must be in the future" validation keeps passing as the real clock moves.
const SEND_AT = dayjs().add(7, 'day').startOf('minute').toISOString()

interface FakeServer {
    flow: HogFlowApi
    schedules: HogFlowScheduleApi[]
    batchJobs: HogFlowBatchJobApi[]
    patches: Record<string, any>[]
    failNextScheduleCreate: boolean
}

let server: FakeServer
let scheduleSeq = 0

function makeSchedule(overrides: Partial<HogFlowScheduleApi>): HogFlowScheduleApi {
    scheduleSeq += 1
    return {
        id: `schedule-${scheduleSeq}`,
        rrule: ONE_TIME_RRULE,
        starts_at: SEND_AT,
        timezone: 'UTC',
        status: 'active',
        next_run_at: null,
        created_at: '',
        updated_at: '',
        ...overrides,
    } as HogFlowScheduleApi
}

function makeFlow(status: string, audience: Record<string, any>[] = AUDIENCE): HogFlowApi {
    return {
        id: BROADCAST_ID,
        name: 'Spring launch',
        status,
        origin_product: 'broadcasts',
        conversion: null,
        email_sending_rate_limit: null,
        actions: [
            { id: 'trigger_node', type: 'trigger', config: { type: 'batch', filters: { properties: audience } } },
            {
                id: 'email_node',
                type: 'function_email',
                config: {
                    template_id: 'template-email',
                    inputs: {
                        email: {
                            value: {
                                to: { email: '{{ person.properties.email }}' },
                                from: { integrationId: 1 },
                                subject: 'Spring is here',
                                text: '',
                                html: '<p>Hello</p>',
                                design: null,
                            },
                        },
                    },
                },
            },
            { id: 'exit_node', type: 'exit', config: { reason: 'Broadcast sent' } },
        ],
        edges: [],
    } as unknown as HogFlowApi
}

function triggerFilters(actions: any[] | undefined): unknown {
    return actions?.find((action) => action.type === 'trigger')?.config?.filters
}

function serverFlow(): HogFlowApi {
    return { ...server.flow, schedules: server.schedules.map((s) => ({ ...s })) } as HogFlowApi
}

// Mirrors the backend contract the wizard talks to, including the pause on audience change
// (`_pause_schedules_on_audience_change`) and the read-only schedule `status`.
function installFakeServer(): void {
    api.hogFlowsRetrieve.mockImplementation(async () => serverFlow())
    api.hogFlowsCreate.mockImplementation(async () => {
        throw new Error('this broadcast already exists')
    })
    api.hogFlowsPartialUpdate.mockImplementation(async (_projectId, _id, body: any) => {
        server.patches.push(body)
        const before = triggerFilters(server.flow.actions as any[])
        server.flow = { ...server.flow, ...body }
        if (body.actions && JSON.stringify(before) !== JSON.stringify(triggerFilters(body.actions))) {
            server.schedules = server.schedules.map((s) =>
                s.status === 'active' ? ({ ...s, status: 'paused' } as HogFlowScheduleApi) : s
            )
        }
        return serverFlow()
    })
    api.hogFlowsUserBlastRadiusCreate.mockImplementation(
        async () => ({ affected: 10, total: 100, limit: null, confirm_token: 'confirm-token' }) as any
    )
    api.hogFlowsBatchJobsList.mockImplementation(async () => server.batchJobs)
    api.hogFlowsBatchJobsCreate.mockImplementation(async () => {
        const job = { id: `job-${server.batchJobs.length + 1}`, status: 'queued' } as HogFlowBatchJobApi
        server.batchJobs = [job, ...server.batchJobs]
        return job
    })
    api.hogFlowsSchedulesList.mockImplementation(async () => server.schedules.map((s) => ({ ...s })))
    api.hogFlowsSchedulesCreate.mockImplementation(async (_projectId, _id, body: any) => {
        if (server.failNextScheduleCreate) {
            server.failNextScheduleCreate = false
            throw new Error('schedule service unavailable')
        }
        const schedule = makeSchedule({ rrule: body.rrule, starts_at: body.starts_at, timezone: body.timezone })
        server.schedules = [schedule, ...server.schedules]
        return schedule
    })
    api.hogFlowsSchedulesDestroy.mockImplementation(async (_projectId, _id, scheduleId) => {
        server.schedules = server.schedules.filter((s) => s.id !== scheduleId)
    })
    api.hogFlowsSchedulesPartialUpdate.mockImplementation(async (_projectId, _id, scheduleId, body: any) => {
        // `status` is read-only on the real serializer, so a client can't resume a paused schedule.
        const { status: _ignored, ...writable } = body ?? {}
        server.schedules = server.schedules.map((s) => (s.id === scheduleId ? { ...s, ...writable } : s))
        return server.schedules.find((s) => s.id === scheduleId)!
    })
}

async function mountLoaded(): Promise<ReturnType<typeof broadcastWizardLogic.build>> {
    const logic = broadcastWizardLogic({ id: BROADCAST_ID })
    await expectLogic(logic, () => logic.mount()).toFinishAllListeners()
    return logic
}

function scheduleSummaries(): Pick<HogFlowScheduleApi, 'rrule' | 'starts_at' | 'timezone' | 'status'>[] {
    return server.schedules.map(({ rrule, starts_at, timezone, status }) => ({ rrule, starts_at, timezone, status }))
}

describe('broadcastWizardLogic', () => {
    let logic: ReturnType<typeof broadcastWizardLogic.build> | null = null

    beforeEach(() => {
        jest.clearAllMocks()
        jest.spyOn(lemonToast, 'success').mockImplementation(() => undefined as any)
        jest.spyOn(lemonToast, 'error').mockImplementation(() => undefined as any)
        scheduleSeq = 0
        server = { flow: makeFlow('draft'), schedules: [], batchJobs: [], patches: [], failNextScheduleCreate: false }
        installFakeServer()
        initKeaTests()
    })

    afterEach(() => {
        logic?.unmount()
        logic = null
    })

    describe('move to draft', () => {
        it.each([
            ['a one-time send that has not fired', 'active', [{}], [], true],
            ['a recurring send that has already run', 'active', [{ rrule: WEEKLY_RRULE }], ['completed'], true],
            ['a live broadcast whose schedule was paused', 'active', [{ status: 'paused' }], [], true],
            ['a broadcast that was sent immediately', 'active', [], ['completed'], false],
            ['a one-time send whose run already started', 'active', [{}], ['active'], false],
            ['a draft', 'draft', [{}], [], false],
            ['an archived broadcast', 'archived', [{}], [], false],
        ])('offers it for %s: %s', async (_name, status, schedules, jobStatuses, expected) => {
            server.flow = makeFlow(status)
            server.schedules = schedules.map((overrides) => makeSchedule(overrides as Partial<HogFlowScheduleApi>))
            server.batchJobs = jobStatuses.map((jobStatus, i) => ({ id: `job-${i}`, status: jobStatus }) as any)

            logic = await mountLoaded()

            expect(logic.values.canMoveToDraft).toBe(expected)
        })

        it('returns a scheduled broadcast to an editable draft with its settings intact', async () => {
            server.flow = makeFlow('active')
            server.schedules = [makeSchedule({ timezone: 'Europe/Paris' })]
            logic = await mountLoaded()
            const before = {
                name: logic.values.name,
                audienceProperties: logic.values.audienceProperties,
                email: logic.values.email,
                scheduleMode: logic.values.scheduleMode,
                sendAt: logic.values.sendAt,
                scheduleTimezone: logic.values.scheduleTimezone,
            }
            expect(before).toMatchObject({ scheduleMode: 'later', sendAt: SEND_AT, scheduleTimezone: 'Europe/Paris' })

            let release: () => void = () => {}
            const gate = new Promise<void>((resolve) => {
                release = resolve
            })
            const realPatch = api.hogFlowsPartialUpdate.getMockImplementation()!
            api.hogFlowsPartialUpdate.mockImplementationOnce(async (...args) => {
                await gate
                return realPatch(...args)
            })

            logic.actions.moveToDraft()
            expect(logic.values.movingToDraft).toBe(true)
            release()
            await expectLogic(logic).toFinishAllListeners()

            expect(server.patches).toEqual([{ status: 'draft' }])
            expect(server.flow.status).toBe('draft')
            expect(logic.values).toMatchObject({
                movingToDraft: false,
                isReadOnly: false,
                currentStep: 'review',
                ...before,
            })
            expect(logic.values.broadcast?.status).toBe('draft')
        })

        it('keeps the broadcast live and retryable when the request fails', async () => {
            server.flow = makeFlow('active')
            server.schedules = [makeSchedule({})]
            logic = await mountLoaded()
            api.hogFlowsPartialUpdate.mockRejectedValueOnce({ detail: 'Permission denied' })

            await expectLogic(logic, () => logic!.actions.moveToDraft()).toFinishAllListeners()

            expect(server.flow.status).toBe('active')
            expect(logic.values).toMatchObject({ movingToDraft: false, isReadOnly: true, canMoveToDraft: true })
            expect(lemonToast.error).toHaveBeenCalled()
        })

        it('relaunches with a fresh active schedule after the audience was edited', async () => {
            server.flow = makeFlow('active')
            server.schedules = [makeSchedule({})]
            logic = await mountLoaded()

            await expectLogic(logic, () => logic!.actions.moveToDraft()).toFinishAllListeners()
            logic.actions.setAudienceProperties(WIDER_AUDIENCE as any)
            await expectLogic(logic, () => logic!.actions.launchBroadcast()).toFinishAllListeners()

            expect(server.flow.status).toBe('active')
            expect(scheduleSummaries()).toEqual([
                { rrule: ONE_TIME_RRULE, starts_at: SEND_AT, timezone: 'UTC', status: 'active' },
            ])
        })
    })

    describe('launch replaces existing schedules', () => {
        it.each([
            [
                'a one-time send over a paused schedule',
                [{ status: 'paused' }],
                'later',
                [{ rrule: ONE_TIME_RRULE, starts_at: SEND_AT, timezone: 'UTC', status: 'active' }],
