import '@testing-library/jest-dom'

import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react'

import { dayjs } from 'lib/dayjs'

import { useMocks } from '~/mocks/jest'
import { initKeaTests } from '~/test/init'

import * as generatedApi from 'products/workflows/frontend/generated/api'

import { BroadcastScene } from './BroadcastScene'

jest.mock('products/workflows/frontend/generated/api')

const api = jest.mocked(generatedApi)

const SEND_AT = dayjs().add(7, 'day').startOf('minute').toISOString()

const liveBroadcast = (userAccessLevel: string): any => ({
    id: 'broadcast-1',
    name: 'Spring launch',
    status: 'active',
    origin_product: 'broadcasts',
    user_access_level: userAccessLevel,
    actions: [
        { id: 'trigger_node', type: 'trigger', config: { type: 'batch', filters: { properties: [] } } },
        {
            id: 'email_node',
            type: 'function_email',
            config: {
                inputs: {
                    email: {
                        value: {
                            to: { email: '{{ person.properties.email }}' },
                            from: { integrationId: 1 },
                            subject: 'Spring is here',
                            html: '<p>Hello</p>',
                            text: '',
                            design: null,
                        },
                    },
                },
            },
        },
    ],
    schedules: [{ id: 's1', rrule: 'FREQ=DAILY;COUNT=1', starts_at: SEND_AT, timezone: 'UTC', status: 'active' }],
})

describe('BroadcastScene', () => {
    beforeEach(() => {
        jest.resetAllMocks()
        useMocks({ post: { '/api/environments/:team_id/query/': () => [200, { results: [] }] } })
        initKeaTests()
        api.hogFlowsBatchJobsList.mockResolvedValue([])
        api.hogFlowsUserBlastRadiusCreate.mockResolvedValue({ affected: 1, total: 1, limit: null } as any)
    })

    afterEach(() => {
        cleanup()
    })

    it('moves a live broadcast to an editable draft after confirming', async () => {
        const broadcast = liveBroadcast('editor')
        api.hogFlowsRetrieve.mockResolvedValue(broadcast)
        api.hogFlowsPartialUpdate.mockResolvedValue({ ...broadcast, status: 'draft' })

        render(<BroadcastScene id="broadcast-1" />)
        fireEvent.click(await screen.findByText('Move to draft'))
        expect(api.hogFlowsPartialUpdate).not.toHaveBeenCalled()
        fireEvent.click(await screen.findByTestId('broadcast-move-to-draft-confirm'))

        await waitFor(() => expect(screen.getByText('Schedule broadcast')).toBeInTheDocument())
        expect(api.hogFlowsPartialUpdate).toHaveBeenCalledWith(expect.anything(), 'broadcast-1', { status: 'draft' })
        expect(screen.queryByText('Move to draft')).not.toBeInTheDocument()
    })

    it('disables it for a viewer', async () => {
        api.hogFlowsRetrieve.mockResolvedValue(liveBroadcast('viewer'))

        render(<BroadcastScene id="broadcast-1" />)
        fireEvent.click(await screen.findByText('Move to draft'))

        expect(screen.queryByTestId('broadcast-move-to-draft-confirm')).not.toBeInTheDocument()
        expect(api.hogFlowsPartialUpdate).not.toHaveBeenCalled()
    })
})

