export type BroadcastStatus = 'draft' | 'scheduled' | 'sending' | 'sent' | 'failed' | 'archived'

const RUNNING_BATCH_JOB_STATUSES = ['waiting', 'queued', 'active']

export interface BroadcastRowDetails {
    latestBatchJob: HogFlowBatchJobApi | null
    totals: Record<string, number>
}

export function getBroadcastStatus(
    broadcast: HogFlowMinimalApi,
    details: BroadcastRowDetails | undefined
): BroadcastStatus {
    if (broadcast.status === 'draft') {
        return 'draft'
    }
    if (broadcast.status === 'archived') {
        return 'archived'
    }
    const latestJob = details?.latestBatchJob
    if (latestJob) {
        if (RUNNING_BATCH_JOB_STATUSES.includes(latestJob.status ?? '')) {
            return 'sending'
        }
        if (latestJob.status === 'completed') {
            return 'sent'
        }
        // Without this a failed or cancelled run falls through to the no-run fallback below, which
        // tells the sender another send is still pending when nothing is coming.
        return 'failed'
    }
    // Active with no batch job yet: it's waiting on its schedule (or a manual send).
    return 'scheduled'
}

// A live broadcast can go back to draft while it still has a send ahead of it. A paused schedule
// counts: relaunching from draft is how it gets an active schedule again. A run already in progress
// is not stopped by a status change, so the move is not offered then.
export function canMoveBroadcastToDraft(broadcast: HogFlowApi | null, batchJobs: HogFlowBatchJobApi[]): boolean {
    if (broadcast?.status !== 'active') {
        return false
    }
    if (batchJobs.some((job) => RUNNING_BATCH_JOB_STATUSES.includes(job.status ?? ''))) {
        return false
    }
    return (broadcast.schedules ?? []).some((schedule) => schedule.status !== 'completed')
}

